#define ALL(a)  (a).begin(),(a).end()

#define pb push_back

#define sz size()







string pre(string s){   // "][" を空白に置き換え

    string b="";

    rep(i,s.sz-1){

        if(s[i]==']' && s[i+1]=='['){

            b+=' ';

            i++;

        }

        else{

            b+=s[i];

        }

    }

    b+=s[s.sz-1];

    return b;

}





string solve(int n,bool check,string s){

    n++;

    string tmp[10000]={};



    int count=0;

    REP(j,n,s.sz){

        if(s[j]!=']'){

            if(s[j]!=' '){

                tmp[count]+=s[j];

            }

            else{

                count++;

            }

        }

        else break;

    }

    vi a;

    rep(i,count+1){

        a.pb(stoi(tmp[i]));

    }

    sort(ALL(a));



    int sum=0;

    rep(i,count/2+1){

        if(check==false)

            sum+=a[i]/2+1;

        else

            sum+=a[i];

    }

    return to_string((sum));

}





string delSpace(string s){  // "] [" を "][" に置き換え

    string ret="";

    rep(i,s.sz-2){

        if(s[i]==']' && s[i+1]==' ' && s[i+2]=='['){

            ret+="][";

            i+=2;

        }

        else{

            ret+=s[i];

        }

    }

    ret+=s[s.sz-2];

    ret+=s[s.sz-1];

    return ret;

}





