        cin >> V[i];



    for(int mask = 0;mask < (1 << N);mask++){

        MAX[mask][0] = mask;

        MAX[mask][1] = -1;



        for(int i = 0;(1 << i) <= mask;i++){

            if((1 << i) & mask){

                int nmask = mask ^ (1 << i);

                join(mask,nmask);

            }

        }

