    int N;

    cin >> N;



    for(int i = 0;i < (1 << N);i++)

        cin >> V[i];



    for(int mask = 0;mask < (1 << N);mask++){

        MAX[mask][0] = mask;

        MAX[mask][1] = -1;



        for(int i = 0;(1 << i) <= mask;i++){

            if((1 << i) & mask){

                int nmask = mask ^ (1 << i);

                join(mask,nmask);

            }

        }

        if(MAX[mask][1] != -1)

            DP[mask] = V[MAX[mask][1]];

        DP[mask] += V[MAX[mask][0]];

    }



    for(int i = 1;i < (1 << N);i++){

        DP[i] = max(DP[i],DP[i - 1]);

        cout << DP[i] << '\n';

    }



    return 0;

}


