template <class T>inline void read(T &x){

    x=0;int ne=0;char c;

    while(!isdigit(c=getchar()))ne=c=='-';

    x=c-48;

    while(isdigit(c=getchar()))x=(x<<3)+(x<<1)+c-48;

    x=ne?-x:x;return ;

}

const int maxn=200005;

const int inf=0x7fffffff;

int n,nn,a[maxn],b[maxn],c[maxn],mx=-inf,mi=inf;

