#define FOR(i,n,m) for(int i=n; i<(int)m; i++)

#define ROF(i,n,m) for(int i=n; i>(int)m; i--)

#define pb push_back

#define lb lower_bound

#define ub upper_bound

#define F first

#define S second

#define ri(a) scanf("%d",&a)

#define rii(a,b) ri(a),ri(b)

#define riii(a,b,c) rii(a,b),ri(c)

