const int INF = 0x3f3f3f3f;

const ll INFLL = 1e18;

const int MOD = 1e9+7;

const int MAXN = 1<<19;



ii dp[MAXN];

int A[MAXN];

int n;



ii f(int mask){

    if(dp[mask].F != -1) return dp[mask];

    if(!mask) return dp[mask] = {0, -1};

    int mxi = 0, mxi2 = -1;

    for(int s = 0 ; s = (s - mask) & mask ;) {

        if(A[mxi] < A[s]) mxi2 = mxi, mxi = s;

        else if(mxi2 == -1 || A[mxi2] < A[s]) mxi2 = s;

    }

    return dp[mask] = {mxi, mxi2};

}



void mxze(int &a, int b){

    a = max(a,b);

}

void mnze(int &a, int b){

    a = min(a,b);

}



int main(){

    //ios_base::sync_with_stdio(false);

    //cin.tie(NULL);



    FOR(i,0,MAXN) dp[i] = {-1,-1};

    ri(n);

    FOR(i,0,1<<n) ri(A[i]);



    int ans = 0;

    FOR(i,1,1<<n){

        ii p = f(i);

        mxze(ans, A[p.F] + A[p.S]);

        printf("%d\n", ans);

    }



    return 0;

}

