#include <bits/stdc++.h>



using namespace std;



typedef long long ll;



const int N = 16;



ll dp[1 << N], cost[1 << N], a[N + 1][N + 1];

int n;



vector<int> get_bits(int mask)

{

    vector<int> bits;



    for(int i = 0; (1 << i) <= mask; i++)

        if((1 << i) & mask)

            bits.push_back(i);



    return bits;

}



ll solve(int mask)

{

    // cout << "enter: " << mask << endl;



    ll &ans = dp[mask];



    if(ans != -1)

        return ans;



    ans = cost[mask];

    auto bits = get_bits(mask);

    int sz = bits.size();



    for(int submasks = 1; submasks < (1 << sz); submasks++)

    {

        int next = 0;

        for(int i = 0; i < sz; i++)

            if((1 << i) & submasks)

                next |= 1 << bits[i];



        ans = max(ans, cost[next] + solve(mask & ~next));

    }



    // cout << mask << " " << ans << endl;



    return ans;

}



int main()

{

    ios_base::sync_with_stdio(false);

    cin.tie(0);

    cout.tie(0);



    memset(dp, -1, sizeof(dp));



    cin >> n;



    for(int i = 0; i < n; i++)

        for(int j = 0; j < n; j++)

            cin >> a[i][j];



    for(int mask = 0; mask < (1 << n); mask++)

    {

        auto bits = get_bits(mask);

        int sz = bits.size();



        for(int i = 0; i < sz; i++)

            for(int j = i + 1; j < sz; j++)

                cost[mask] += a[bits[i]][bits[j]];

    }



    // cout << "here" << endl;

    // exit(0);



    cout << solve((1 << n) - 1) << endl;



    return 0;

}

