using namespace std;

#define fi first

#define se second

typedef long long ll;

const ll mod=1000000007;

ll powmod(ll a,ll b) {ll res=1;a%=mod; assert(b>=0); for(;b;b>>=1){if(b&1)res=res*a%mod;a=a*a%mod;}return res;}

ll gcd(ll a,ll b) { return b?gcd(b,a%b):a;}



int dp[100001];

vector<int> stone;

int k;

int solve(int n){

	if(dp[n] > -1) return dp[n];

	if(n == 0){

		return dp[n] = 0;

	}

	int minimum = INT_MAX;

	for(int i = 1; i <= k; i++){

		if(n - i >= 0){

			minimum = min(minimum, solve(n-i) + abs(stone[n] - stone[n - i]));

		}

	}

	return dp[n] = minimum;

}

int main()

{

	ios::sync_with_stdio(false);

  	cin.tie(0);

  	int n;

  	cin >> n >> k;

  	stone.resize(n);

  	for(int i = 0; i < n; i++){

  		int m;

  		cin >> m;

  		stone[i] = m;

  	}

  	for(int i = 0; i < 100001; i++) dp[i] = -1;

  	reverse(stone.begin(), stone.end());

  	cout << solve(n-1) << endl;

	return 0;

}

