int dp[mx], h[mx], n, k;



int solve( int i)

{

    if(i==n)

        return 0;



    if(dp[i]!= -1)

        return dp[i];





    int ret= inf;



    for(int j=1; j<=k; j++)

    {

        if(i+j<=n)

            ret= min(ret, (abs(h[i]- h[i+j])+ solve(i+j)));

    }





    return dp[i]= ret;

}



