#include <bits/stdc++.h>

using namespace std;

const int N=1e5+5;

int A[N];

char ans[N],ch,q;

bool ac[N];

int n,x,m;

int main(){

    scanf("%d %d",&m,&n);

    for(int i=0;i<n;++i){

        scanf("%d %c%c",&x,&ch,&q);

        if(ch=='A') ac[x]=1;

        else if(!ac[x])A[x]++;

    }

    int sum=0 , sAc=0;

    for(int i=1;i<=m;++i){

        sum+=A[i]*ac[i];

        sAc+=ac[i];

    }

    printf("%d %d\n",sAc,sum);

