#include <bits/stdc++.h>



using namespace std;



#define endl '\n'

#define all(x) (x).begin(), (x).end()

#define rall(x) (x).rbegin(), (x).rend()

#define ms(arr, value) memset(arr, value, sizeof arr)

#define ll    int64_t



const int oo  = (int)(1e9);

const ll lloo  = (ll)(1e18);



const int N = 1e5 + 10;



class Task {

public:



    int n, k;

    vector<int> A;



    ll dp[N];



    ll go(int index) {

        if(index > n) return 0LL;

        if(index == n) {

            return 0LL;

        }



        ll &ans = dp[index];

        if(ans != -1) return ans;



        ll x = oo;



        for(int i = 1; i <= k; ++i){            

            if(index+i <= n) {

                x = min(x, abs(A[index]-A[index+i]) + go(index + i));

            }

        }

        if(x == oo) {

            x = 0;

        }

        ans = x;

        return ans;

    }





    ll solveOne(istream &in, ostream &out) {

        in >> n >> k;

        A.resize(n+1);

        for(int i = 1; i <= n; ++i){

            in >> A[i];

        }

        memset(dp, -1, sizeof dp);

        ll ans = go(1);

        return ans;  

    }



    void solve(istream &in, ostream &out) {

        int t=1;

        while(t--) {

            out << solveOne(in, out) << endl;

        }

    }

};



