	if(dp[pos] != -1)

		return dp[pos];

	if (pos == (n - 1))

		return 0;

	if (pos > n)

		return oo;

	int answer = oo;

	for(int i = 1; i <= k; i++)

		answer = min(answer, f(pos + i) + abs(v[pos] - v[pos + i]));

	return dp[pos] = answer;

}

