using namespace std;



typedef pair<int, int> pii;

typedef pair<ll, ll> pll;

const ll inf = 1e16 + 3;

const int mod = 1e9 + 7;

const int lim = 2e5 + 2;



int N, K;

ll hi[lim];



ll dp[lim];

int mark[lim];



ll DynamicProgramming(int idx)

{

    if(idx <= 0)

        return 0;



    if(mark[idx])

        return dp[idx];



    mark[idx] = true;



    DynamicProgramming(idx - 1);

    DynamicProgramming(idx - 2);





    int kidx =max(0,idx - K);

    ll aux = inf;

    for(int i = kidx; i < idx; i++)

    {

        ll curr = dp[i] + abs(hi[i] - hi[idx]);

        aux = min(aux, curr);

    }



    dp[idx] = aux;

    return dp[idx];

}





