#include<bits/stdc++.h>

#define read(x) scanf("%d",&x)

using namespace std;

typedef long long LL;

const int maxn=5e5+5;

int a[maxn],c[maxn];

int sum[maxn];

int n;

LL tmp;

int lowbit(int x) {

    return x&(-x);

}

int getsum(int x) {

    int sum=0;

    while(x>0) {

        sum+=c[x];

        x-=lowbit(x);

    }

    return sum;

}

void add(int x) {

    while(x<maxn) {

        c[x]+=1;

        x+=lowbit(x);

    }

}

bool check(int x) {

    memset(c,0,sizeof(c));

    sum[0]=0;

    for(int i=1;i<=n;i++) {

        if(a[i]>=x)sum[i]=1;

        else sum[i]=-1;

        sum[i]=sum[i-1]+sum[i];

    }

    for(int i=0;i<=n;i++) {

        sum[i]+=n+1;

    }

    LL ans=0;

    for(int i=0;i<=n;i++) {

        ans+=getsum(sum[i]);

        add(sum[i]);

    }

    if(ans>=tmp)return true;

    else return false;

}

int main() {

    read(n);

    int minn=1e9,maxx=0;

    for(int i=1;i<=n;i++) {

        read(a[i]);

        minn=min(minn,a[i]);

        maxx=max(maxx,a[i]);

    }

    int l=minn,r=maxx;

    int ans=l;

    tmp=1LL*(n+1)*n/4;

    while(l<=r) {

        int mid=(l+r)/2;

        if(check(mid)) {

            l=mid+1;

            ans=mid;

        }

        else r=mid-1;

    }

    printf("%d\n",ans);

}

