int lowbit(int x){

	return x&-x;

}

void add(int x){

	for(int i=x;i<=2*N;i+=lowbit(i))

		c[i]++;

}

int query(int x){

	ll sum=0;

	for(int i=x;i>=1;i-=lowbit(i))

		sum+=c[i];

	return sum;

}

