    for(int i=1;i<=2*N;i++)c[i]=0;		//用memset会出错 

	for(int i=1;i<=n;i++){

		s[i]=s[i-1]+(a[i]>=now ?1 :-1);

		//if(now==9)printf("%d ",s[i]);

	}

	//printf("\n");

	ll sum=0;

	for(int i=0;i<=n;i++){

		sum+=query(s[i]+N);

		add(s[i]+N);

	}

	//printf("%d %d\n",now,sum);

	return sum>=1ll*n*(n+1)/4;

}

