#include <bits/stdc++.h>

using namespace std;

using ll = long long;



template<typename T> struct BIT {

    int max_n;

    vector<T> data;

    const bool zi;

    const T unit;

    BIT<T>(int n, bool zi = true, T u = T(0)) : max_n(n), zi(zi), unit(u) {

        data.assign(max_n + 1, u);

    }

    void add(int i, T x) {

        if ( zi ) i++;

        assert( i > 0 );

        while ( i <= max_n ) {

            data[i] += x;

            i += i & -i;

        }

    }

    T sum(int i) {

        if ( zi ) i++;

        assert( i > 0 );

        T s = unit;

        while ( i > 0 ) {

            s += data[i];

            i -= i & -i;

        }

        return s;

    }

    vector<T> get_sum_list(int l, int r) {

        vector<T> ret;

        for ( int i = l; i <= r; i++ ) {

            ret.push_back(sum(i));

        }

        return ret;

    }

};



ll solve() {

    ll N;

    cin >> N;

    vector<ll> A(N);

    for ( int i = 0; i < N; i++ ) {

        cin >> A[i];

    }



    vector<ll> xs1(A);

    sort(xs1.begin(), xs1.end());

    xs1.erase(unique(xs1.begin(), xs1.end()), xs1.end());

    for ( int ii = 0; ii < A.size(); ii++ ) {

        A[ii] = lower_bound(xs1.begin(), xs1.end(), A[ii]) - xs1.begin();

    }



    BIT<ll> bit(N+1);

    ll ans = 0;

    for ( int i = 0; i < N; i++ ) {

        ans += i - bit.sum(A[i]);

        bit.add(A[i], 1);

    }



    return ans;

}



int main() {

    auto ans = solve();

    cout << ans << "\n";

    return 0;

}

