struct segtree{

  int N;

  P dat[2 * MAX_N - 1];

  segtree(){}

  segtree(int n){

    N = 1;

    while(n > N) N *= 2;



    rep(i, 2 * N - 1) dat[i] = MP(-10000000, -10000000);

    for(int i = N - 1; i < 2 * N - 1; i++) dat[i] = MP(0, -1 * (i - N + 1));

  }



  void update(int k, int a){

    k += N - 1;

    dat[k].F += a;

    while(k > 0){

