using namespace std;



int solve(const int stones_height[], int memo[], const int &n, const int &k){

    int ans;

    if(memo[n] != -1) ans = memo[n];

    else if(n == 1) return 0;

    else{

        ans = abs(stones_height[n] - stones_height[n - 1]) + solve(stones_height, memo, n - 1, k);

        for(int i = 2; n - i >= 1 && i <= k; i++){

            ans = min(ans, abs(stones_height[n] - stones_height[n - i]) + solve(stones_height, memo, n - i, k));

        }

    }

    return memo[n] = ans;

}



int main(){

    int n, k;

    while(scanf("%d %d", &n, &k) != EOF){

        int stones_height[n + 1], memo[n + 1];

        for(int i = 0; i < n; i++){

            scanf("%d", &stones_height[i + 1]);

            memo[i + 1] = -1;

        }

        printf("%d\n", solve(stones_height, memo, n, k));

    }

    return 0;

}

