typedef long double ld;

const double PI = acos(-1.0);

ld eps = 1e-9;



vector<lli> bit(MAX, 0);

void clean() { // O(MAX)

	for(int i = 0; i < MAX; i++) bit[i] = 0;	

}

lli F(lli a, lli b){return a + b;}



void update(int i, lli val) { // O(log(MAX))

	for(i++; i < MAX; i += i & -i) 

		bit[i] = F(bit[i], val);

}

lli query(int i) { // O(log(MAX))

	lli ans = 0;

	for(i++; i; i -= i & -i) ans = F(ans, bit[i]);

	return ans;

}

int main() {

	optimizar_io

	int n; cin >> n;

	lli b, c; 

	vector<lli> v(n);

	vector<int> bucket(MAX);

	fore(i, 0, n) {

		cin >> v[i];

		bucket[v[i]]++;

	}

	fore(i, 0, bucket.size()) {

		lli ele = bucket[i] * i;

		update(i, ele);

	}

	int q; cin >> q;

	fore(i, 0, q) {

		cin >> b >> c;

		lli actual = -b * bucket[b];

		update(b, actual);

		actual = -c * bucket[c];

		update(c, actual);

		bucket[c] += bucket[b];

		bucket[b] = 0;

		lli up = bucket[c] * c;

		update(c, up);

		cout << query(MAX) << endl;

	}

}

