#include <bits/stdc++.h>

using namespace std;



typedef long long ll;



#define INF 1e18

#define MAX_N 100005



ll N, K, h[MAX_N], memo[MAX_N];



ll dp(int p) {

  if (p < 1) {

  	return INF;

  }

  if (p == 1) {

  	return 0;

  }

  if (p <= K + 1) {

  	return abs(h[p] - h[1]);

  }

  ll opt = INF;

  for (int i = 1; i <= K; i++) {

  	opt = min(opt, abs(h[p] - h[p - i]) + dp(p - i));

  }

  return memo[p] = opt;

}



int main() {

  scanf("%lli %lli", &N, &K);

  for (int i = 1; i <= N; i++) {

  	scanf("%lli", &h[i]);

  }

  // printf("%lli\n", dp(N));

  for (int i = 2; i <= 1 + K; i++) {

  	memo[i] = abs(h[i] - h[1]);

  }

  for (int i = 2 + K; i <= N; i++) {

  	ll opt = INF;

  	for (int j = 1; j <= K; j++) {

  	  opt = min(opt, abs(h[i] - h[i - j]) + memo[i - j]);

	}

	memo[i] = opt;

  }

  printf("%lli\n", memo[N]);

}

