using namespace std;

#define ll long long

#define MX 100005



const ll INF = 1e12;



int A[MX];

ll dp[MX];

int n, k;



ll recur(int pos){

    if (pos == 1) return dp[pos] = 0;

    if (pos == 2) return dp[pos] = abs(A[2] - A[1]);

    if (dp[pos] != -1) return dp[pos];



    ll mn = INF;

    for (int i = 1; i <= k; i++){

        if (pos - i >= 1){

            mn = min(mn, recur(pos - i) + abs(A[pos] - A[pos - i]));

        }

        else break;

    }

    return dp[pos] = mn;

}

int main()

{

    scanf("%d%d", &n, &k);

    for (int i = 1; i <= n; i++){

        scanf("%d", &A[i]);

        dp[i] = -1;

    }



    ll ans = recur(n);

    printf("%lld\n", ans);

    return 0;

}

