#define fastIO cout << fixed << setprecision(12), ios::sync_with_stdio(false), cin.tie(nullptr), cout.tie(nullptr)

double const EPS = 1e-12, PI = acos(-1);

const int N = 4e5 + 9, M = 5e3 + 9, OO = 1e9 + 7, MOD = 1e9 + 7;

const ll inf = 1e18;



int arr[N];

pair<int, int> DP[N];



pair<int, int> merge(pair<int, int> A, pair<int, int> B) {

  set<pair<int, int>> st; // maximum Val, without repeat index

  st.insert({-arr[A.first], A.first});

  st.insert({-arr[A.second], A.second});

  st.insert({-arr[B.first], B.first});

  st.insert({-arr[B.second], B.second});

  pair<int, int> ans;

  ans.first = (*st.begin()).second;

  st.erase(st.begin());

  ans.second = (*st.begin()).second;

  return ans;

}



int main() {

  fastIO;

#ifdef LOCAL

  freopen("input.in", "rt", stdin);

#endif

  // problem on SOS DP

  int n;

  cin >> n;

  for (int i = 0; i < (1 << n); ++i) {

    cin >> arr[i];

    DP[i] = {i, (1 << n)};

  }

  for (int i = 0; i < n; ++i) {

    for (int mask = 0; mask < (1 << n); ++mask) {

      if(mask & (1 << i)) {

        DP[mask] = merge(DP[mask], DP[mask ^ (1 << i)]); // SOS

      }

    }

  }

  int best = 0;

  for (int i = 0; i < (1 << n); ++i) {

    best = max(best, arr[DP[i].first] + arr[DP[i].second]);

    if(i)

      cout << best << '\n';

  }

  return 0;

}

