	if(dp[stone]==-1){

		if(stone == n-1){

			return 0;

		}

		else{

			dp[stone] = INT_MAX;

			for(int i=1; i<=k && stone+i<n; i++){

				dp[stone] = min(dp[stone], jump(stone+i) + abs(h[stone]-h[stone+i]));

			}

			return dp[stone];

		}

	}

	else{

		return dp[stone];

	}

}



