int main() {

	ios::sync_with_stdio(false);

	cin.tie(0);

	int n, k;

	cin >> n >> k;

	if (n < k) {

		int h1, h2;

		cin >> h1;

		for (int i = 1; i < n; i++) {

			cin >> h2;

		}

		cout << abs(h2 - h1);

		return 0;

	}

	vector<int> heights;

	vector<int> costs = {0};

	int h1;

	cin >> h1;

	heights.push_back(h1);

	for (int i = 1; i < k; i++) {

		int h2;

		cin >> h2;

		heights.push_back(h2);

		costs.push_back(abs(h2 - h1));

	}

	for (int i = k; i < n; i++) {

		int h2;

		cin >> h2;

		int best_cost = costs.back() + abs(heights.back() - h2);

		heights.push_back(h2);

		for (int j = 1; j <= k; j++) {

			int cost = costs[costs.size() - j];

			int h1 = heights[costs.size() - j];

			best_cost = min(best_cost, cost + abs(h2 - h1));

		}

		costs.push_back(best_cost);

	}

	cout << costs.back();

	return 0;

}

