using namespace std;



typedef long long ll;



const int N = 1 * 1e5 + 10;

const ll inf = 1e18;



ll res;

ll a[N];

ll dp[N];



ll go(ll idx, ll k, ll n){

	if(idx == n)	return 0;

	if(dp[idx] != -1)	return dp[idx];

	ll mn = inf;

	for (int i = idx + 1; i <= min(n, idx + k); ++i){

		mn = min(abs(a[idx] - a[i]) + go(i, k, n), mn);

	}

	return dp[idx] = mn;

}



void solve() {

	ll n, k;

	cin >> n >> k;

	for (int i = 1; i <= n ; ++i){

		cin >> a[i];

	}

	memset(dp, -1, sizeof(dp));

	cout << go(1, k, n);

}



