{

    memset(bit,0,sizeof(bit));

    memset(ais,0,sizeof(ais));

    for(int i=1;i<=n;i++) ais[i]=(ais[i-1]+(a[i]>=x?1:-1));

    cnt=0;

    for(int i=0;i<=n;i++)

    {

        cnt+=sum(ais[i]+N);

        add(ais[i]+N,1);

    }

    return cnt>=1ll*(n+1)*n/4;

}



