{

    memcpy(b,a,sizeof(a));

    sort(b+1,b+n+1);

    int l=0,r=n+1,m=(l+r)/2;

    while(l+1<r)

    {

        if(Che(b[m])) l=m;else r=m;

        m=(l+r)/2;

    }

    return b[l];

}



